import{_ as o,a0 as i,w as r,s as p,I as a,x as e,a1 as n,A as l,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"与开放社区讨论法律事宜的 7 种方式 | LCTT x X-CMD","titleTemplate":false,"description":"与开放社区讨论法律事宜的 7 种方式 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"与开放社区讨论法律事宜的 7 种方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"与开放社区讨论法律事宜的 7 种方式 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170321 7 ways to discuss legal matters with an open community","title":"与开放社区讨论法律事宜的 7 种方式","tag":"201707","desc":""},"relativePath":"201707/20170321 7 ways to discuss legal matters with an open community.md","filePath":"[post].md"}'),u={name:"201707/20170321 7 ways to discuss legal matters with an open community.md"};function d(f,t,g,h,x,T){const s=i("Link");return r(),p("div",null,[t[21]||(t[21]=a("h1",{id:"与开放社区讨论法律事宜的-7-种方式",tabindex:"-1"},[e("与开放社区讨论法律事宜的 7 种方式 "),a("a",{class:"header-anchor",href:"#与开放社区讨论法律事宜的-7-种方式","aria-label":"Permalink to “与开放社区讨论法律事宜的 7 种方式”"},"​")],-1)),t[22]||(t[22]=a("blockquote",null,[a("p",null,"你的组织的律师准备好与开源社区打交道了么？不要让他们犯这些错。")],-1)),t[23]||(t[23]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/law/LAW-Internet_construction_9401467_520x292_0512_dc.png?itok=xmtgmowQ",alt:"7 ways to discuss legal matters with an open community",title:"7 ways to discuss legal matters with an open community"})],-1)),a("p",null,[t[2]||(t[2]=e("我注意到有相当多的人尝试与[开源推进联盟的许可证评估社区] ",-1)),n(s,{href:"https://opensource.org/approval"},{default:l(()=>[...t[0]||(t[0]=[e("3",-1)])]),_:1}),t[3]||(t[3]=e("以及 ",-1)),n(s,{href:"https://www.apache.org/legal/"},{default:l(()=>[...t[1]||(t[1]=[e("Apache 软件基金会的法律事务委员会",-1)])]),_:1}),t[4]||(t[4]=e("建立沟通，当轮到_你_与开放社区进行法律讨论时，我想提供一些成功的提示和技巧。",-1))]),t[24]||(t[24]=m('<h3 id="不要代理人" tabindex="-1">不要代理人 <a class="header-anchor" href="#不要代理人" aria-label="Permalink to “不要代理人”">​</a></h3><p>首先，也是最重要的是，要确保进行谈话的人员既是_有资格的_，也是_有授权的_。不要用代理人，这只会让社区沮丧，他们很快会发现你的代表总是扮演二手车推销员的角色并且要求到后面的房间交易。显然，法律讨论将涉及公司的一个团队，可能涉及产品管理、工程和内部咨询。 但代表们需要能够自己控制谈话内容，不要总是引用幕后某个匿名人物的话。</p><h3 id="多边主义" tabindex="-1">多边主义 <a class="header-anchor" href="#多边主义" aria-label="Permalink to “多边主义”">​</a></h3><p>开源社区就安全合作所需的确定性达成了难得一致的共识。这种共识体现在其治理中，尤其是在他们使用的开源许可证中。所以当你提出一个新的提案时，就不像是一个普通的商业交易。这些是双边谈判，以双方的自由为代价来创造一个最佳妥协的和平条约。在这个讨论中，你只是许多方面之一，你需要解释为什么你的提案对所有人都有益。写上多边之间的调整本质上是缓慢的，所以不要设置最后期限。无论你做什么，不要建议对开源许可证进行更改！</p><h3 id="首先学习" tabindex="-1">首先学习 <a class="header-anchor" href="#首先学习" aria-label="Permalink to “首先学习”">​</a></h3><p>现有的共识和过程其存在是有原因的。你应该了解每个元素的原因，最好连同其发生的历史一起了解，然后再提出修改。这样，你可以在进一步发展的背景下表达你的提案，这样你可以避免在社区历史中受教育（浪费社区资源，降低你机会的有效性）。回看邮件列表，并向开发人员询问历史和来龙去脉。</p><h3 id="透明" tabindex="-1">透明 <a class="header-anchor" href="#透明" aria-label="Permalink to “透明”">​</a></h3><p>开源开发人员使用一个迭代、增量修改的过程。即使需要大的变化，它几乎总是用一系列更小、更好的解释或不言而喻的正确变化来实现的，这样每个人都可以跟进并支持。你提出的更改也是如此。不要弄出新的贡献者协议或者修改过的许可证，并期望每个人都相信你是专家、一切都是对的。你需要提供一根“红线”（相当于法律文件的差异），记录每个变化，并提供一个承认任何社区影响并为其辩护的理由。如果你_只是_为了你自己的利益需要一个东西，那就承认它，而不是希望没有人会注意到。</p><h3 id="谦逊" tabindex="-1">谦逊 <a class="header-anchor" href="#谦逊" aria-label="Permalink to “谦逊”">​</a></h3><p>你是一个炙手可热的律师，而你认为只有程序员才使用邮件列表。很明显，对你而言他们缺乏讨论的经验，所以你安排了一个你认为是同等的代理人，简化这一切，或者提出与社区选择的律师进行一对一的讨论。 我很抱歉地说你做的全都是错的。由于社区的政策是多边协商一致的，所以他们很有可能知道他们为什么定下现在的这些决定。名单上的一些人将具有优秀的领域知识，可能会比你的更好。而且一对一这件事是终极的羞辱，就像询问是否有一个成年人可以与你说话。</p><h3 id="不要秘密渠道" tabindex="-1">不要秘密渠道 <a class="header-anchor" href="#不要秘密渠道" aria-label="Permalink to “不要秘密渠道”">​</a></h3><p>有可能在某种领导机构，也许你认识在公司法务工作的 VP，也许你认识社区的总法律顾问。虽然在某些情况下，询问如何操控流程的提示可能是可以接受的，但尝试通过秘密渠道讨论或协商来试图影响甚至决定结果，那么结果会很糟糕。你最终可能会被邀请进行一对一的讨论, 但你不应该要求或期待它。</p><h3 id="成为一个成员" tabindex="-1">成为一个成员 <a class="header-anchor" href="#成为一个成员" aria-label="Permalink to “成为一个成员”">​</a></h3><p>如果你一切都做得正确，那么社区就有可能尊重你。坚持这些。作为一名冷静、机智的贡献者建立你的声誉。当人们犯你犯过的错误（或者已避免的）时，帮助他们。作为邮件列表社区的值得信赖的参与者，你是项目和雇主的真正资产。继续贡献，一些项目最终会在它们的治理中为你提供一个角色。</p>',14)),a("p",null,[a("em",null,[t[6]||(t[6]=e("这个文章的早期版本",-1)),n(s,{href:"https://meshedinsights.com/2017/02/28/engaging-communities-on-legal-matters-7-tips/"},{default:l(()=>[...t[5]||(t[5]=[e("最初发表",-1)])]),_:1}),t[7]||(t[7]=e("在 Meshed Insights 中。",-1))])]),t[25]||(t[25]=a("p",null,"（题图： opensource.com）",-1)),t[26]||(t[26]=a("hr",null,null,-1)),t[27]||(t[27]=a("p",null,"作者简介：",-1)),t[28]||(t[28]=a("p",null,"Simon Phipps - 计算机行业和开源老手 Simon Phipps 上线了 Public Software，一个欧洲的开源项目托管，Document Foundation 的志愿者总监。他的帖子由 Patreon 赞助者赞助 - 如果你想要看更多，成为其中一个！",-1)),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),n(s,{href:"https://opensource.com/open-organization/17/3/legal-matters-community"},{default:l(()=>[...t[8]||(t[8]=[e("https://opensource.com/open-organization/17/3/legal-matters-community",-1)])]),_:1})]),a("p",null,[t[13]||(t[13]=e("作者：",-1)),n(s,{href:"https://opensource.com/users/simonphipps"},{default:l(()=>[...t[10]||(t[10]=[e("Simon Phipps",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const y=o(u,[["render",d]]);export{P as __pageData,y as default};
